-- Dungeon maps from the game's own minimap pictures, for floors that have no map art in the client (WoW: Forever's new
-- dungeons). The client has the pictures its minimap draws inside these instances: one per terrain tile outdoors,
-- several per building part indoors. Data/MinimapArtData.lua (generated by tools/minimap_art.py from the game files)
-- says which pictures (by file ID) make up each floor, where each one lies, and how the plan's coordinates map onto
-- the result; this module turns that into the art the map canvas draws. No picture is shipped.
--
-- Which art a plan floor gets (MinimapArt.Choose), first that applies:
--   1. the game's map art for the floor's uiMap (Instances.MapArt);
--   2. the old dungeon map tiles (GameFiles.FloorArt; the classic dungeons);
--   3. Santiago Reyes' bundled map of a Forever floor (Data/ReyesMaps.lua);
--   4. another addon's drawn map (Providers.FloorArt: Dungeon Journal, Forever Dungeon Routes, OpenMap);
--   5. the minimap pictures (this module), drawn in the parchment colours unless the player chose the game's
--      (UI/MapCanvas.lua ArtStyle);
--   6. none: the parchment grid.
-- With "Prefer drawn maps" switched off (it is on by default), the minimap pictures come before 3 and 4.

local _, ns = ...
local MinimapArt = ns:NewModule("MinimapArt")
local Util = ns.Util

local cache = {}

-- The data of floor `index` of an instance name, or nil.
function MinimapArt.Data(name, index)
	local data = ns.MinimapArtData
	local k = type(name) == "string" and ns.GameFiles.Key(name)
	local floors = k and type(data) == "table" and data[k]
	return type(floors) == "table" and floors[index] or nil
end

-- Does the generated table cover this instance at all? (for /dp debug)
function MinimapArt.Has(name)
	local k = type(name) == "string" and ns.GameFiles.Key(name)
	return k ~= nil and type(ns.MinimapArtData) == "table" and ns.MinimapArtData[k] ~= nil
end

-- A floor's pieces laid out in map units: { { file, x, y, w, h, coords = { 8 texture coordinates } } } (pure).
function MinimapArt.Pieces(d)
	local out = {}
	for _, p in ipairs(type(d) == "table" and d.pieces or {}) do
		if type(p) == "table" and Util.IsInteger(p[1]) and #p >= 13 then
			out[#out + 1] = { file = p[1], x = p[2], y = p[3], w = p[4], h = p[5],
				coords = { p[6], p[7], p[8], p[9], p[10], p[11], p[12], p[13] } }
		end
	end
	return out
end

-- Does a piece show its picture turned or cut so that part of the box lies outside the picture? (Those are drawn with
-- a clamp to transparent, so the box's corners stay empty.)
function MinimapArt.Overhangs(coords)
	for _, c in ipairs(coords) do
		if c < -0.001 or c > 1.001 then
			return true
		end
	end
	return false
end

-- The plan -> map transform as the canvas's alignment ({ mode = "fit", sx, kx, tx, ky, sy, ty }: map x = sx * x +
-- kx * y + tx, map y = ky * x + sy * y + ty).
function MinimapArt.Align(xf)
	if type(xf) ~= "table" or #xf ~= 6 then
		return nil
	end
	return { mode = "fit", sx = xf[1], kx = xf[2], tx = xf[3], ky = xf[4], sy = xf[5], ty = xf[6], error = 0 }
end

-- Plan (x, y) -> map (x, y) through an alignment (per-axis, or with the cross terms kx, ky).
function MinimapArt.ToMap(a, x, y)
	if not a then
		return x, y
	end
	return x * a.sx + (a.kx or 0) * y + a.tx, (a.ky or 0) * x + y * a.sy + a.ty
end

-- Map (x, y) -> plan (x, y): the inverse (identity when the transform cannot be inverted).
function MinimapArt.FromMap(a, x, y)
	if not a then
		return x, y
	end
	local kx, ky = a.kx or 0, a.ky or 0
	local det = a.sx * a.sy - kx * ky
	if math.abs(det) < 1e-12 then
		return x, y
	end
	local dx, dy = x - a.tx, y - a.ty
	return (a.sy * dx - kx * dy) / det, (-ky * dx + a.sx * dy) / det
end

-- The art of floor `index` of a plan, in the shape Instances.MapArt returns (width, height, textures) plus pieces,
-- align and source = "minimap"; nil when the instance or floor is not covered. The zone outside (Floors.IsOutside)
-- gets none, as with the old map tiles.
function MinimapArt.FloorArt(plan, index)
	local floor = type(plan) == "table" and type(plan.floors) == "table" and plan.floors[index]
	if type(floor) ~= "table" or ns.Floors.IsOutside(floor) then
		return nil
	end
	local name = plan.instance and plan.instance.name
	local pos = floor.art or index -- a floor with `art` (Data/Floors.lua): that position in the instance's art
	local key = tostring(ns.GameFiles.Key(name or "")) .. ":" .. tostring(pos)
	if cache[key] == nil then
		local d = MinimapArt.Data(name, pos)
		local pieces = d and MinimapArt.Pieces(d) or {}
		if d and #pieces > 0 and type(d.w) == "number" and type(d.h) == "number" and d.w > 0 and d.h > 0 then
			local textures = {}
			for i, p in ipairs(pieces) do
				textures[i] = p.file
				p.clamp = MinimapArt.Overhangs(p.coords)
			end
			cache[key] = { width = d.w, height = d.h, tileWidth = d.w, tileHeight = d.h, textures = textures,
				pieces = pieces, align = MinimapArt.Align(d.xf), source = "minimap", kind = d.source }
		else
			cache[key] = false
		end
	end
	return cache[key] or nil
end

-- Does the player want drawn maps (Santiago Reyes' bundled maps, another addon's) over the minimap pictures?
-- (settings.preferProviderMaps, on by default.)
function MinimapArt.PreferProviders()
	return not (ns.db ~= nil and ns.db.settings.preferProviderMaps == false)
end

-- The art to draw for floor `index` of a plan whose map is uiMapID (MinimapArt's header has the order). Returns art
-- (nil for the grid) and its source: "map", "tiles", "reyes", "provider", "minimap" or "grid".
function MinimapArt.Choose(plan, index, uiMapID, preferProviders)
	if ns.Instances.MapArt(uiMapID) then
		return nil, "map"
	end
	local art = ns.GameFiles.FloorArt(plan, index)
	if art then
		return art, "tiles"
	end
	local mini = MinimapArt.FloorArt(plan, index)
	if mini and preferProviders == nil then
		preferProviders = MinimapArt.PreferProviders()
	end
	if mini and not preferProviders then
		return mini, "minimap"
	end
	art = ns.ReyesMaps.FloorArt(plan, index)
	if art then
		return art, "reyes"
	end
	art = ns.Providers.FloorArt(plan, index)
	if art then
		return art, "provider"
	end
	if mini then
		return mini, "minimap"
	end
	return nil, "grid"
end

-- The source of every floor of a plan, for /dp debug and /dp scan: { "minimap", "provider:dungeonJournal", ... }.
function MinimapArt.Sources(plan)
	local out = {}
	for i = 1, #(plan and plan.floors or {}) do
		local mapID = ns.Journal.FloorMap(plan, i)
		local art, source = MinimapArt.Choose(plan, i, mapID)
		out[i] = source == "provider" and art and art.provider and (source .. ":" .. art.provider) or source
	end
	return out
end

function MinimapArt.Reset()
	cache = {}
end

-- Every recommended plan's floors by art source, for /dp debug: counts { map = n, tiles = n, reyes = n, minimap = n,
-- provider = n, grid = n } and the floors on the grid ({ "Hyjal Summit 1", ... }).
function MinimapArt.Summary()
	local counts, grid = { map = 0, tiles = 0, reyes = 0, minimap = 0, provider = 0, grid = 0 }, {}
	for _, plan in ipairs(ns.Bundled.All()) do
		for i, source in ipairs(MinimapArt.Sources(plan)) do
			local f = plan.floors[i]
			-- The zone outside is not a dungeon floor: not counted.
			if not ns.Floors.IsOutside(f) then
				local base = source:match("^[^:]+")
				counts[base] = (counts[base] or 0) + 1
				if base == "grid" then
					grid[#grid + 1] = ns.Names.Instance(plan.instance) .. " " .. i
				end
			end
		end
	end
	return counts, grid
end
